// Filter items: Production Status = 'Ready to Schedule' AND Scheduling Status = 'Not Scheduled'
const rows = $input.all().map(i => i.json);
const candidates = rows.filter(r => {
  const prod = String(r['Production Status'] || '').trim();
  const sched = String(r['Scheduling Status'] || '').trim();
  return prod === 'Ready to Schedule' && sched === 'Not Scheduled';
});

if (candidates.length === 0) {
  return [{ json: { count: 0, has_items: false } }];
}

const masterReadyFolderId = $env.DRIVE_05_01_READY_TO_SCHEDULE_FOLDER_ID || '05_01_READY_TO_SCHEDULE_MASTER_ID';
const masterFolderUrl = `https://drive.google.com/drive/folders/${masterReadyFolderId}`;

// Build HTML table
let tableRows = '';
for (const c of candidates) {
  const dt = `${c['Recommended Publish Date'] || 'TBD'} ${c['Recommended Publish Time'] || ''}`.trim();
  tableRows += `
  <tr style='border-bottom: 1px solid #30363d;'>
    <td style='padding: 10px 14px;'><strong>${c.Business || ''}</strong></td>
    <td style='padding: 10px 14px;'>${c['Marketing Job'] || c.Campaign || ''}</td>
    <td style='padding: 10px 14px;'><span style='background:#21262d;color:#58a6ff;padding:3px 8px;border-radius:12px;font-size:12px;'>${c['Content Format'] || ''}</span></td>
    <td style='padding: 10px 14px;'>📅 ${dt}</td>
    <td style='padding: 10px 14px;'><a href='${c['Final Asset Link'] || masterFolderUrl}' target='_blank' style='color:#58a6ff;text-decoration:underline;'>Open Package</a></td>
  </tr>`;
}

const digestHtml = `
<!DOCTYPE html>
<html>
<body style='font-family:-apple-system,sans-serif;background:#0d0f12;color:#f0f0f0;padding:24px;'>
  <div style='max-width:720px;margin:0 auto;background:#161a22;border:1px solid #30363d;border-radius:12px;overflow:hidden;'>
    <div style='background:#000;padding:20px 24px;border-bottom:2px solid #d4af37;'>
      <h2 style='margin:0;color:#d4af37;'>TUDDEH Daily Ready-to-Schedule Digest</h2>
      <p style='margin:4px 0 0;color:#8b949e;font-size:13px;'>The following ${candidates.length} item(s) are approved and awaiting manual scheduling.</p>
    </div>
    <div style='padding:20px 24px;'>
      <table style='width:100%;border-collapse:collapse;font-size:14px;color:#c9d1d9;'>
        <thead>
          <tr style='background:#21262d;color:#8b949e;text-align:left;font-size:12px;text-transform:uppercase;'>
            <th style='padding:8px 14px;'>Business</th>
            <th style='padding:8px 14px;'>Job</th>
            <th style='padding:8px 14px;'>Format</th>
            <th style='padding:8px 14px;'>Recommended Time</th>
            <th style='padding:8px 14px;'>Action</th>
          </tr>
        </thead>
        <tbody>
          ${tableRows}
        </tbody>
      </table>
      <div style='margin-top:24px;text-align:center;'>
        <a href='${masterFolderUrl}' target='_blank' style='display:inline-block;padding:12px 24px;background:#238636;color:#fff;border-radius:8px;font-weight:600;text-decoration:none;'>📂 Open Master 01 Ready to Schedule Folder</a>
      </div>
    </div>
  </div>
</body>
</html>`;

return [{
  json: {
    count: candidates.length,
    has_items: true,
    email_subject: `[TUDDEH DIGEST] ${candidates.length} Content Item(s) Ready to Schedule`,
    email_html: digestHtml,
    recipient: $env.TUDDEH_APPROVAL_EMAIL || 'team@tuddeh.com'
  }
}];

// Zero items waiting to schedule. Silent termination as per spec.
return [{
  json: {
    status: 'SILENT_EXIT',
    message: 'Zero items in Ready to Schedule state. No email sent.'
  }
}];
